<?php
session_start();
require_once __DIR__ . '/../includes/dbconn.php';
require_once __DIR__ . '/../includes/check-login.php';
check_login();
$userId = (int)$_SESSION['id'];
$stmt = $mysqli->prepare('SELECT firstName,middleName,lastName,email,regNo FROM userregistration WHERE id=? LIMIT 1');
$stmt->bind_param('i',$userId); $stmt->execute(); $student=$stmt->get_result()->fetch_assoc(); $stmt->close();
$booking = null;
if ($student) {
    $stmt = $mysqli->prepare('SELECT roomno,seater,feespm,stayfrom,duration,course FROM registration WHERE regno=? ORDER BY id DESC LIMIT 1');
    $stmt->bind_param('s',$student['regNo']); $stmt->execute(); $booking=$stmt->get_result()->fetch_assoc(); $stmt->close();
}
?>
